            event_id = event.get("id", "anonymous:" + str(pos))
            if sequence_first:
                rank = (sequence, event.get("revision", 0), pos)
            else:
                rank = (event.get("revision", 0), pos)
            if event_id not in chosen or rank > chosen[event_id][0]:
                chosen[event_id] = (rank, event)

        balances = dict(data.get("opening", {}))
        mode = data["rounding"]

        def rounded(n, d):
            return (n + d // 2) // d if mode == "half_up" else n // d

        for _, event in chosen.values():
            if event.get("void", False):
                continue
            raw = event["price"] * event.get("quantity", 1)
            discount = min(10000, max(0, event.get("discount_bp", 0)))
            net = rounded(raw * (10000 - discount), 10000)
            base = net if discounted_base else raw
            tax = rounded(base * event.get("tax_bp", 0), 10000)
            total = net + tax
            if event.get("kind") == "refund":
                total = -total
            key = event.get("account", "default") + "|" + event.get("currency", "USD")
            balances[key] = balances.get(key, 0) + total
        return {"balances": balances}
    return solve


def _dependency_resolver():
    from itertools import product

    def solve(data):
        packages = data["packages"]
        names = sorted(packages)
        features = set(data.get("features", []))
        blocked = data.get("blocked", {})
        pins = data.get("pins", {})
        roots = data["roots"]
        options = [[-1] + sorted(row["version"] for row in packages[name])
                   for name in names]
        rows_by_version = {
            name: {row["version"]: row for row in rows}
            for name, rows in packages.items()
        }

        def valid(assignment):
            versions = dict(zip(names, assignment))
            for name, (low, high) in roots.items():
                version = versions[name]
                if version == -1 or not low <= version <= high:
                    return False
            edges = {name: [] for name in names if versions[name] != -1}
            for name, version in versions.items():
                if version == -1:
                    continue
                if version in blocked.get(name, []):
                    return False
                if name in pins and version != pins[name]:
                    return False
                row = rows_by_version[name][version]
                for dep in row.get("deps", []):
                    feature = dep.get("feature", "")
                    if feature and feature not in features:
                        continue
                    other = dep["name"]
                    other_version = versions[other]
                    if other_version == -1 or not dep["min"] <= other_version <= dep["max"]:
                        return False
                    edges[name].append(other)

            active, finished = set(), set()

            def visit(name):
                if name in active:
                    return False
                if name in finished:
                    return True
                active.add(name)
                for other in edges[name]:
                    if not visit(other):
                        return False
                active.remove(name)
                finished.add(name)
                return True

            return all(visit(name) for name in edges)

        for assignment in product(*options):
            if valid(assignment):
                return {"versions": {name: version for name, version
                                     in zip(names, assignment) if version != -1}}
        return {"error": "unsatisfiable"}
    return solve


def _quota_intervals():
    from itertools import combinations

    def solve(data):
        jobs = data["jobs"]
        k = data["k"]
        blocked = set(data.get("blocked", []))
        mandatory = set(data.get("mandatory", []))
        quotas = data.get("quotas", {})
        best = None
        best_value = None
        available = [job for job in jobs if job["id"] not in blocked]
        if len(available) < k or mandatory & blocked:
            return {"error": "impossible"}
        for subset in combinations(available, k):
            ids = {job["id"] for job in subset}
            if not mandatory <= ids:
                continue
            counts = {}
            for job in subset:
                counts[job["group"]] = counts.get(job["group"], 0) + 1
            if any(not low <= counts.get(group, 0) <= high
                   for group, (low, high) in quotas.items()):
                continue
            ordered = sorted(subset, key=lambda job: (job["start"], job["end"]))
            if any(ordered[i]["start"] < ordered[i - 1]["end"]
                   for i in range(1, len(ordered))):
                continue
            selected = sorted(job["id"] for job in subset)
            value = sum(job["value"] for job in subset)
            if (best is None or value > best_value or
                    (value == best_value and selected < best)):
                best, best_value = selected, value
        if best is None:
            return {"error": "impossible"}
        return {"selected": best, "value": best_value}
    return solve


def _temporal_routes():
    import heapq

    def solve(data):
        required = data.get("required", [])
        bit = {node: 1 << i for i, node in enumerate(required)}
        full = (1 << len(required)) - 1
        graph = [[] for _ in range(data["n"])]
        for edge in data["edges"]:
            graph[edge["u"]].append(edge)
        source = data["source"]
        initial_mask = bit.get(source, 0)
        start_state = (source, 0, initial_mask)
        best = {start_state: data["start"]}
        queue = [(data["start"], source, 0, initial_mask)]
        coupons = data["coupons"]
        while queue:
            time, node, used, mask = heapq.heappop(queue)
            state = (node, used, mask)
            if best.get(state) != time:
                continue
            if node == data["target"] and used == coupons and mask == full:
                return {"arrival": time}
            for edge in graph[node]:
                depart = max(time, edge["open"])
                if depart >= edge["close"]:
                    continue
                choices = [(edge["duration"], used)]
                if used < coupons:
                    duration = max(2, edge["duration"] - edge.get("discount", 0))
                    choices.append((duration, used + 1))
                for duration, next_used in choices:
                    arrival = depart + duration
                    if arrival > data["deadline"]:
                        continue
                    dest = edge["v"]
                    next_mask = mask | bit.get(dest, 0)
                    next_state = (dest, next_used, next_mask)
                    if arrival < best.get(next_state, float("inf")):
                        best[next_state] = arrival
                        heapq.heappush(queue, (arrival, dest, next_used, next_mask))
        return {"arrival": None}
    return solve


